Sum all salaries while tracking the minimum and maximum, then subtract both from the sum and divide by `n - 2`. Use a `long long` for the sum to be safe.

```cpp
class Solution {
public:
    double average(vector<int>& salary) {
        long long sum = 0;
        int mn = INT_MAX, mx = INT_MIN;
        for (int s : salary) {
            sum += s;
            mn = min(mn, s);
            mx = max(mx, s);
        }
        return (double)(sum - mn - mx) / (salary.size() - 2);
    }
};
```

