class Solution {
public:
    string abbreviateProduct(int left, int right) {
        int c2 = 0, c5 = 0;
        for (int i = left; i <= right; i++) {
            int x = i;
            while (x % 2 == 0) { x /= 2; c2++; }
            x = i;
            while (x % 5 == 0) { x /= 5; c5++; }
        }
        int C = min(c2, c5);
        int rem2 = C, rem5 = C;
        long long LIM = 10000000000LL;
        long long val = 1;
        bool big = false;
        long long suf = 1;
        long double ls = 0;
        for (int i = left; i <= right; i++) {
            int x = i;
            while (x % 2 == 0 && rem2 > 0) { x /= 2; rem2--; }
            while (x % 5 == 0 && rem5 > 0) { x /= 5; rem5--; }
            if (!big) {
                val *= x;
                if (val >= LIM) big = true;
            }
            suf = (suf * x) % 100000;
            ls += log10l((long double)x);
        }
        string res;
        if (!big) {
            res = to_string(val);
        } else {
            long double f = ls - floorl(ls);
            long long pre = (long long)powl(10.0L, f + 4);
            if (pre > 99999) pre = 99999;
            string s = to_string(suf);
            while (s.size() < 5) s = "0" + s;
            res = to_string(pre) + "..." + s;
        }
        res += "e" + to_string(C);
        return res;
    }
};
```

