traces.inference_trace:
Approach: process the hits in reverse using union-find, with a virtual root node for the top row.

1. Copy the grid and remove every brick that will be hit. Only cells that actually held a brick are marked, so a hit on an empty cell does nothing.
2. Build the union-find on the remaining grid. Bricks in row 0 are unioned with the virtual root node `m*n`. Each component tracks its size.
3. Go through the hits in reverse. For a hit that removed a brick:
   - Record the root's size before restoring, `before = size(find(top))`.
   - Restore the brick, union it with the root if it is in row 0, and union it with every adjacent brick.
   - Record `after = size(find(top))`.
   - The answer for this hit is `max(0, after - before - 1)`. The `-1` excludes the restored brick itself.
4. For a hit on an empty cell, the answer is 0.

All hits are unique, so each cell is restored at most once. Cells are indexed as `i*n+j`, and the virtual root is `m*n`.

```cpp
class Solution {
public:
    vector<int> p, sz;
    int find(int x) {
        while (p[x] != x) {
            p[x] = p[p[x]];
            x = p[x];
        }
        return x;
    }
    void unite(int a, int b) {
        a = find(a);
        b = find(b);
        if (a == b) return;
        p[a] = b;
        sz[b] += sz[a];
    }
    vector<int> hitBricks(vector<vector<int>>& grid, vector<vector<int>>& hits) {
        int m = grid.size(), n = grid[0].size();
        vector<vector<int>> g = grid;
        int k = hits.size();
        vector<char> had(k, 0);
        for (int i = 0; i < k; i++) {
            int x = hits[i][0], y = hits[i][1];
            if (g[x][y] == 1) {
                had[i] = 1;
                g[x][y] = 0;
            }
        }
        int top = m * n;
        p.assign(m * n + 1, 0);
        sz.assign(m * n + 1, 1);
        for (int i = 0; i <= m * n; i++) p[i] = i;
        int dx[4] = {1, -1, 0, 0}, dy[4] = {0, 0, 1, -1};
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (!g[i][j]) continue;
                if (i == 0) unite(i * n + j, top);
                if (i > 0 && g[i - 1][j]) unite(i * n + j, (i - 1) * n + j);
                if (j > 0 && g[i][j - 1]) unite(i * n + j, i * n + j - 1);
            }
        }
        vector<int> res(k, 0);
        for (int t = k - 1; t >= 0; t--) {
            if (!had[t]) continue;
            int x = hits[t][0], y = hits[t][1];
            int before = sz[find(top)];
            g[x][y] = 1;
            if (x == 0) unite(x * n + y, top);
            for (int d = 0; d < 4; d++) {
                int nx = x + dx[d], ny = y + dy[d];
                if (nx < 0 || ny < 0 || nx >= m || ny >= n || !g[nx][ny]) continue;
                unite(x * n + y, nx * n + ny);
            }
            int after = sz[find(top)];
            res[t] = max(0, after - before - 1);
        }
        return res;
    }
};
```

