Approach: keep two Fenwick trees (BIT) indexed by value (1..1e5), one for counts and one for sums, covering the last m elements. The sum of the middle elements is the sum of the smallest (m−k) elements minus the sum of the smallest k elements.

To get the sum of the smallest t elements, descend the BIT to find the largest value position pos where cumulative count ≤ t. Then add the sum up to pos, plus (t − count up to pos) × (pos+1), since the remaining elements all have value pos+1.

Implementation:
- Maintain a deque (or a circular array) of the last m elements.
- addElement: push num and update the BIT with +1 count and +num sum. If the size exceeds m, pop the front and update the BIT with −1 and −value.
- calculateMKAverage: if size < m, return -1. Otherwise compute (S(m−k) − S(k)) / (m − 2k) using long long.

The BIT descent: with LOG = 17 (2^17 = 131072 > 1e5) and N = 100000, start with pos = 0. For step from 2^16 down to 1: if pos+step ≤ N and cnt[pos+step] ≤ remaining, then pos += step, remaining −= cnt[pos], and sum += sm[pos]. At the end, remaining elements (if any) have value pos+1, so add remaining × (pos+1). The condition uses ≤, so it takes as many full value groups as possible. If remaining is 0 at the end, nothing is added. Otherwise the next value's count exceeds the remaining, and the leftover is taken from value pos+1. This is correct.

```cpp
#include <vector>
#include <deque>
using namespace std;

class MKAverage {
    static const int N = 100000;
    vector<long long> cnt, sm;
    deque<int> dq;
    int m, k;
    void upd(int i, int c, long long s) {
        for (; i <= N; i += i & -i) {
            cnt[i] += c;
            sm[i] += s;
        }
    }
    long long smallest(int t) {
        int pos = 0;
        long long rem = t, sum = 0;
        for (int step = 1 << 16; step > 0; step >>= 1) {
            int np = pos + step;
            if (np <= N && cnt[np] <= rem) {
                pos = np;
                rem -= cnt[np];
                sum += sm[np];
            }
        }
        sum += rem * (long long)(pos + 1);
        return sum;
    }
public:
    MKAverage(int m, int k) {
        this->m = m;
        this->k = k;
        cnt.assign(N + 1, 0);
        sm.assign(N + 1, 0);
    }

    void addElement(int num) {
        dq.push_back(num);
        upd(num, 1, num);
        if ((int)dq.size() > m) {
            int v = dq.front();
            dq.pop_front();
            upd(v, -1, -v);
        }
    }

    int calculateMKAverage() {
        if ((int)dq.size() < m) return -1;
        long long total = smallest(m - k) - smallest(k);
        return (int)(total / (m - 2 * k));
    }
};
```

