For each point i, compute the slope to every later point j as a reduced fraction (dy/dx) and count how many points share each slope. The best count for point i is the largest of these counts plus 1 (for i itself). The answer is the maximum over all i.

To normalize a slope:
- Divide dx and dy by gcd(|dx|, |dy|).
- Fix the sign so that dx > 0, or dx == 0 and dy > 0. Vertical lines then become (0, 1) and horizontal lines (1, 0).
- Encode the pair as a single key: dx is in [0, 20000] and dy is in [-20000, 20000], so `key = dx * 100000LL + (dy + 50000)` is unique. I use a `map<long long, int>` for this.

If n <= 2, return n. The complexity is O(n² log n), which is fine for n = 300.

```cpp
class Solution {
public:
    int maxPoints(vector<vector<int>>& points) {
        int n = points.size();
        if (n <= 2) return n;
        int ans = 1;
        for (int i = 0; i < n; i++) {
            map<long long, int> cnt;
            int best = 0;
            for (int j = i + 1; j < n; j++) {
                int dx = points[j][0] - points[i][0];
                int dy = points[j][1] - points[i][1];
                int g = std::__gcd(abs(dx), abs(dy));
                dx /= g;
                dy /= g;
                if (dx < 0 || (dx == 0 && dy < 0)) {
                    dx = -dx;
                    dy = -dy;
                }
                long long key = (long long)dx * 100000LL + (dy + 50000);
                int c = ++cnt[key];
                best = max(best, c);
            }
            ans = max(ans, best + 1);
        }
        return ans;
    }
};
```

