```cpp
class Solution {
public:
    int countTriples(int n) {
        int cnt = 0;
        for (int a = 1; a <= n; a++) {
            for (int b = 1; b <= n; b++) {
                int s = a * a + b * b;
                int c = (int)sqrt((double)s);
                while (c * c < s) c++;
                while (c * c > s) c--;
                if (c * c == s && c <= n) cnt++;
            }
        }
        return cnt;
    }
};
```

