The maximum possible OR is the OR of all elements, since OR only adds bits. With at most 16 elements there are at most 65536 subsets, so I can enumerate every non-empty subset by bitmask, compute its OR, and count those equal to the maximum.

```cpp
class Solution {
public:
    int countMaxOrSubsets(vector<int>& nums) {
        int n = nums.size();
        int mx = 0;
        for (int x : nums) mx |= x;
        int cnt = 0;
        for (int m = 1; m < (1 << n); m++) {
            int o = 0;
            for (int i = 0; i < n; i++) {
                if (m >> i & 1) o |= nums[i];
            }
            if (o == mx) cnt++;
        }
        return cnt;
    }
};
```

