class Solution {
public:
    int countVowelSubstrings(string word) {
        int n = word.size();
        int cnt = 0;
        auto idx = [](char c) {
            switch (c) {
                case 'a': return 0;
                case 'e': return 1;
                case 'i': return 2;
                case 'o': return 3;
                case 'u': return 4;
            }
            return -1;
        };
        for (int i = 0; i < n; i++) {
            int mask = 0;
            for (int j = i; j < n; j++) {
                int k = idx(word[j]);
                if (k < 0) break;
                mask |= 1 << k;
                if (mask == 31) cnt++;
            }
        }
        return cnt;
    }
};
```

