Use a lazy increment array. `inc[i]` holds an increment that has not yet been applied to element `i` and should also be passed down to element `i-1` when `i` is popped.

- **push:** if the stack size is below `maxSize`, append `x` to the stack and append a `0` to `inc`.
- **increment(k, val):** let `i = min(k, size) - 1`. If `i >= 0`, add `val` to `inc[i]`.
- **pop:** if the stack is empty, return `-1`. Otherwise let `i = size - 1` and compute `res = st[i] + inc[i]`. If `i > 0`, add `inc[i]` to `inc[i-1]`. Then remove the top element from both arrays and return `res`.

```cpp
class CustomStack {
public:
    vector<int> st, inc;
    int mx;
    CustomStack(int maxSize) {
        mx = maxSize;
    }

    void push(int x) {
        if ((int)st.size() < mx) {
            st.push_back(x);
            inc.push_back(0);
        }
    }

    int pop() {
        if (st.empty()) return -1;
        int i = st.size() - 1;
        int res = st[i] + inc[i];
        if (i > 0) inc[i - 1] += inc[i];
        st.pop_back();
        inc.pop_back();
        return res;
    }

    void increment(int k, int val) {
        int i = min(k, (int)st.size()) - 1;
        if (i >= 0) inc[i] += val;
    }
};
```

