Process the numbers in order. For the i-th number, the state's digit sum already tells us how many numbers have been placed, so we can iterate over states directly.

Let `dp[state]` be the maximum AND sum after placing the first `cnt(state)` numbers, where `cnt` is the sum of the digits. Start with `dp[0] = 0` and everything else at -1. For each state with `dp[state] >= 0` and `cnt < n`, take the next number `nums[cnt]` and try each slot j with digit < 2. The new state is `state + 3^j`, and its value is `dp[state] + (nums[cnt] & (j+1))`. The answer is the maximum `dp` over states with `cnt == n`.

Iterating states in increasing order works because adding `3^j` always increases the state value. The digit sum is computed per state in O(numSlots), which is cheap.

```cpp
class Solution {
public:
    int maximumANDSum(vector<int>& nums, int numSlots) {
        int n = nums.size();
        int total = 1;
        vector<int> pw(numSlots + 1, 1);
        for (int i = 1; i <= numSlots; i++) pw[i] = pw[i - 1] * 3;
        total = pw[numSlots];
        vector<int> dp(total, -1);
        dp[0] = 0;
        int ans = 0;
        for (int s = 0; s < total; s++) {
            if (dp[s] < 0) continue;
            int cnt = 0;
            vector<int> d(numSlots);
            int t = s;
            for (int j = 0; j < numSlots; j++) {
                d[j] = t % 3;
                t /= 3;
                cnt += d[j];
            }
            if (cnt == n) {
                ans = max(ans, dp[s]);
                continue;
            }
            for (int j = 0; j < numSlots; j++) {
                if (d[j] < 2) {
                    int ns = s + pw[j];
                    int v = dp[s] + (nums[cnt] & (j + 1));
                    if (v > dp[ns]) dp[ns] = v;
                }
            }
        }
        return ans;
    }
};
```

