Approach: run a DFS that records each node's depth and parent. Then x and y are cousins exactly when their depths are equal and their parents differ.

```cpp
/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode() : val(0), left(nullptr), right(nullptr) {}
 *     TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
 *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
 * };
 */
class Solution {
public:
    int dx = -1, dy = -1;
    TreeNode *px = nullptr, *py = nullptr;
    void dfs(TreeNode* n, TreeNode* p, int d, int x, int y) {
        if (!n) return;
        if (n->val == x) { dx = d; px = p; }
        if (n->val == y) { dy = d; py = p; }
        dfs(n->left, n, d + 1, x, y);
        dfs(n->right, n, d + 1, x, y);
    }
    bool isCousins(TreeNode* root, int x, int y) {
        dfs(root, nullptr, 0, x, y);
        return dx == dy && px != py;
    }
};
```

