public:
    vector<int> eventualSafeNodes(vector<vector<int>>& graph) {
        int n = graph.size();
        vector<vector<int>> rev(n);
        vector<int> deg(n);
        queue<int> q;
        for (int i = 0; i < n; i++) {
            deg[i] = graph[i].size();
            for (int j : graph[i]) rev[j].push_back(i);
            if (deg[i] == 0) q.push(i);
        }
        vector<bool> safe(n, false);
        while (!q.empty()) {
            int u = q.front();
            q.pop();
            safe[u] = true;
            for (int p : rev[u]) {
                if (--deg[p] == 0) q.push(p);
            }
        }
        vector<int> res;
        for (int i = 0; i < n; i++) if (safe[i]) res.push_back(i);
        return res;
    }
