                        if (row[r + 1][j + k] - row[r + 1][j] != t) ok = false;
                    }
                    for (int c = j; c < j + k && ok; c++) {
                        if (col[i + k][c + 1] - col[i][c + 1] != t) ok = false;
                    }
                    if (ok) return k;
                }
            }
        }
        return 1;
    }
