traces.inference_trace:
This is a bitmask DP over rows, where each state is the set of occupied seats in a row.

A mask is valid for a row if:
- it uses only good seats,
- it has no two adjacent bits, i.e. `mask & (mask >> 1) == 0`.

Two consecutive row masks `prev` and `cur` are compatible if `cur & (prev << 1) == 0` and `cur & (prev >> 1) == 0`. This forbids the upper-left and upper-right neighbours. The seat directly in front or behind is allowed.

Let `dp[mask]` be the best total for the rows processed so far, with the current row using `mask`. Start with a virtual previous row whose only state is mask 0 with value 0. For each row, compute the new `dp` from every valid `cur` and every reachable `prev`, adding `popcount(cur)`. The answer is the maximum over the last row's `dp`.

The seat characters may be `'.'` or `'#'`. The examples show trailing spaces, but the actual input is `char`, so I compare against `'#'` for broken seats and treat everything else as good.

```cpp
class Solution {
public:
    int maxStudents(vector<vector<char>>& seats) {
        int m = seats.size(), n = seats[0].size();
        int S = 1 << n;
        vector<int> dp(S, -1);
        dp[0] = 0;
        for (int i = 0; i < m; i++) {
            int bad = 0;
            for (int j = 0; j < n; j++) if (seats[i][j] == '#') bad |= (1 << j);
            vector<int> nd(S, -1);
            for (int cur = 0; cur < S; cur++) {
                if (cur & bad) continue;
                if (cur & (cur >> 1)) continue;
                int pc = __builtin_popcount(cur);
                for (int prev = 0; prev < S; prev++) {
                    if (dp[prev] < 0) continue;
                    if (cur & (prev << 1)) continue;
                    if (cur & (prev >> 1)) continue;
                    nd[cur] = max(nd[cur], dp[prev] + pc);
                }
            }
            dp = nd;
        }
        int ans = 0;
        for (int v : dp) ans = max(ans, v);
        return ans;
    }
};
```

