                while (lo < hi) {
                    int mid = (lo + hi + 1) / 2;
                    if (a[mid - 1] * mid - pre[mid] <= rem) lo = mid;
                    else hi = mid - 1;
                }
                long long x = (rem + pre[lo]) / lo;
                x = min(x, (long long)target - 1);
                val += x * partial;
            }
