Since n ≤ 300, brute force works: for each candidate node in `initial`, remove it, run a BFS from the remaining infected nodes, and count the infected nodes. That is O(k·n²) ≈ 27M operations, which is fine.

For each candidate `r` (taken in sorted order so ties go to the smallest index):
1. Mark `r` as removed.
2. Start a BFS from every node in `initial` except `r`.
3. Never visit `r`.
4. Count the visited nodes.

Keep the candidate with the smallest count. On equal counts, keep the one with the smaller index.

Comparing `count < best || (count == best && r < ans)` handles ties without sorting.

```cpp
class Solution {
public:
    int minMalwareSpread(vector<vector<int>>& graph, vector<int>& initial) {
        int n = graph.size();
        int best = INT_MAX, ans = -1;
        for (int r : initial) {
            vector<char> vis(n, 0);
            vis[r] = 1; // removed, treat as visited so never entered
            queue<int> q;
            int cnt = 0;
            for (int s : initial) {
                if (s == r) continue;
                if (!vis[s]) {
                    vis[s] = 1;
                    q.push(s);
                    cnt++;
                }
            }
            while (!q.empty()) {
                int u = q.front();
                q.pop();
                for (int v = 0; v < n; v++) {
                    if (graph[u][v] && !vis[v]) {
                        vis[v] = 1;
                        cnt++;
                        q.push(v);
                    }
                }
            }
            if (cnt < best || (cnt == best && r < ans)) {
                best = cnt;
                ans = r;
            }
        }
        return ans;
    }
};
```

