Initialize `dp` to -1 for unreachable states and `dp[0] = 0`. The answer is `dp[(1<<m) - 1]`.

```cpp
class Solution {
public:
    int maxCompatibilitySum(vector<vector<int>>& students, vector<vector<int>>& mentors) {
        int m = students.size();
        int n = students[0].size();
        vector<vector<int>> sc(m, vector<int>(m, 0));
        for (int i = 0; i < m; i++)
            for (int j = 0; j < m; j++)
                for (int k = 0; k < n; k++)
                    if (students[i][k] == mentors[j][k]) sc[i][j]++;
        vector<int> dp(1 << m, -1);
        dp[0] = 0;
        for (int mask = 0; mask < (1 << m); mask++) {
            if (dp[mask] < 0) continue;
            int i = __builtin_popcount(mask);
            if (i >= m) continue;
            for (int j = 0; j < m; j++) {
                if (mask & (1 << j)) continue;
                int nm = mask | (1 << j);
                dp[nm] = max(dp[nm], dp[mask] + sc[i][j]);
            }
        }
        return dp[(1 << m) - 1];
    }
};
```

