Approach: store every point in a hash set. For each pair of points that could be opposite corners of a rectangle (different x and different y), check whether the other two corners are in the set. If they are, update the minimum area. With n ≤ 500 this is about 125,000 pairs, which is fast.

To encode a point as a key, use `x * 40001 + y` as a `long long`.

To avoid counting each pair twice, iterate over all i < j and require `x1 != x2` and `y1 != y2`. Each diagonal pair is then checked once, and the other diagonal is covered by a different pair, which is fine.

```cpp
class Solution {
public:
    int minAreaRect(vector<vector<int>>& points) {
        unordered_set<long long> s;
        for (auto &p : points) s.insert((long long)p[0] * 40001 + p[1]);
        int n = points.size();
        long long best = LLONG_MAX;
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                int x1 = points[i][0], y1 = points[i][1];
                int x2 = points[j][0], y2 = points[j][1];
                if (x1 == x2 || y1 == y2) continue;
                long long area = (long long)abs(x1 - x2) * abs(y1 - y2);
                if (area >= best) continue;
                if (s.count((long long)x1 * 40001 + y2) && s.count((long long)x2 * 40001 + y1))
                    best = area;
            }
        }
        return best == LLONG_MAX ? 0 : (int)best;
    }
};
```

