Check on example 2, [3,4,5,1,2]: the root is 3, left = [1,2], right = [4,5]. Each side has 1 way, and C(4,2) = 6, so the total is 6 and the answer is 5. ✓.

Implementation:
- Precompute Pascal's triangle mod p up to 1000 (a 1001×1001 table of ints is fine).
- Write a recursive function on a vector that returns the number of orderings mod p. For size ≤ 2 it returns 1; the general case handles this naturally, so no special case is needed beyond the empty or single-element vector.
- Split the vector into left and right, recurse on both, and combine with the binomial coefficient.
- Return (result − 1 + mod) % mod.

Recursion depth is at most 1000, which is fine.

```cpp
class Solution {
public:
    static const int MOD = 1000000007;
    vector<vector<int>> C;
    long long solve(vector<int>& v) {
        int n = v.size();
        if (n <= 2) return 1;
        vector<int> l, r;
        for (int i = 1; i < n; i++) {
            if (v[i] < v[0]) l.push_back(v[i]);
            else r.push_back(v[i]);
        }
        long long a = solve(l), b = solve(r);
        long long res = C[n - 1][l.size()];
        res = res * a % MOD * b % MOD;
        return res;
    }
    int numOfWays(vector<int>& nums) {
        int n = nums.size();
        C.assign(n + 1, vector<int>(n + 1, 0));
        for (int i = 0; i <= n; i++) {
            C[i][0] = 1;
            for (int j = 1; j <= i; j++) {
                C[i][j] = (C[i - 1][j - 1] + (j <= i - 1 ? C[i - 1][j] : 0)) % MOD;
            }
        }
        long long r = solve(nums);
        return (int)((r - 1 + MOD) % MOD);
    }
};
```

