Use a union-find structure. For each request, find the roots of u and v. If the roots are equal, the request succeeds. Otherwise, check every restriction (x, y): if the roots of x and y are exactly the roots of u and v (in either order), merging would connect a restricted pair, so the request fails. If no restriction blocks it, union u and v and mark the request successful.

Each request scans up to 1000 restrictions, so the total work is about 10^6 find operations, which is fine.

```cpp
class Solution {
public:
    vector<int> p;
    int find(int x) {
        while (p[x] != x) {
            p[x] = p[p[x]];
            x = p[x];
        }
        return x;
    }
    vector<bool> friendRequests(int n, vector<vector<int>>& restrictions, vector<vector<int>>& requests) {
        p.resize(n);
        for (int i = 0; i < n; i++) p[i] = i;
        vector<bool> res;
        for (auto& r : requests) {
            int a = find(r[0]), b = find(r[1]);
            if (a == b) {
                res.push_back(true);
                continue;
            }
            bool ok = true;
            for (auto& s : restrictions) {
                int x = find(s[0]), y = find(s[1]);
                if ((x == a && y == b) || (x == b && y == a)) {
                    ok = false;
                    break;
                }
            }
            if (ok) p[a] = b;
            res.push_back(ok);
        }
        return res;
    }
};
```

