Use a bitmask DP over subsets of tasks.

1. Compute `sum[mask]`, the total time of the tasks in `mask`, and mark `valid[mask]` when `sum[mask] <= sessionTime`. A valid mask can be done in one session.
2. Let `dp[mask]` be the minimum number of sessions needed to finish the tasks in `mask`, with `dp[0] = 0`.
3. For each `mask`, enumerate its non-empty submasks `sub`. If `valid[sub]`, then `dp[mask] = min(dp[mask], dp[mask ^ sub] + 1)`.
4. The answer is `dp[(1 << n) - 1]`.

Enumerating all submasks of all masks costs 3^14 ≈ 4.8 million operations, which is fast enough.

```cpp
class Solution {
public:
    int minSessions(vector<int>& tasks, int sessionTime) {
        int n = tasks.size();
        int full = 1 << n;
        vector<int> sum(full, 0), dp(full, 100);
        for (int m = 1; m < full; m++) {
            int low = __builtin_ctz(m);
            sum[m] = sum[m & (m - 1)] + tasks[low];
        }
        dp[0] = 0;
        for (int m = 1; m < full; m++) {
            for (int s = m; s > 0; s = (s - 1) & m) {
                if (sum[s] <= sessionTime) {
                    dp[m] = min(dp[m], dp[m ^ s] + 1);
                }
            }
        }
        return dp[full - 1];
    }
};
```

