1. Split the input into `day`, `month` and `year` tokens.
2. Take the leading digits of the day token (1 or 2 digits) with `stoi`, which stops at the first non-digit character. Zero-pad it to 2 digits.
3. Look up the month's position in a list of abbreviations and zero-pad it to 2 digits.
4. Output `year-month-day`.

The expected output in the examples shows a trailing space ("2052-10-20 "), which is most likely an artifact of how the examples are formatted. The original LeetCode problem returns no trailing space, so I return the string without one.

```cpp
class Solution {
public:
    string reformatDate(string date) {
        stringstream ss(date);
        string d, m, y;
        ss >> d >> m >> y;
        vector<string> months = {"Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"};
        int day = stoi(d);
        int mon = 1;
        for (int i = 0; i < 12; i++) {
            if (m.substr(0, 3) == months[i]) {
                mon = i + 1;
                break;
            }
        }
        string res = y.substr(0, 4) + "-";
        res += (mon < 10 ? "0" : "") + to_string(mon);
        res += "-";
        res += (day < 10 ? "0" : "") + to_string(day);
        return res;
    }
};
```

