Approach: count the minimum number of left and right parentheses to remove, then run a DFS with pruning.

1. Scan the string. For `(`, increment `open`. For `)`, if `open > 0` decrement it, otherwise increment `rmR`. After the scan, `rmL = open`.
2. Run DFS over the characters, tracking the current index, the remaining `rmL` and `rmR`, the current balance, and the built string.
3. For a `(` or `)`, either skip it (if the matching removal count is positive) or keep it.
4. To avoid duplicates, I use a set of result strings. This is fine at this size, since there are at most 20 parentheses.
5. Prune when the balance goes negative, and when a removal count goes negative.
6. At the end of the string, accept the result if `rmL == 0`, `rmR == 0` and `balance == 0`.

Details:
- Keeping `(`: `bal+1`.
- Keeping `)`: only allowed if `bal > 0`, then `bal-1`.
- Removing: `rmL--` for `(` and `rmR--` for `)`.
- Letters are always appended.

Since the removal counts are exactly the minimum, every accepted string has the minimum number of removals.

Example 3, `")("`: the scan gives `rmR=1`, `rmL=1`. Both characters are removed, giving the empty string, so the result is `[""]`. This is correct.

```cpp
class Solution {
public:
    set<string> res;
    string str;
    void dfs(int i, int rmL, int rmR, int bal, string& cur) {
        if (rmL < 0 || rmR < 0 || bal < 0) return;
        if (i == (int)str.size()) {
            if (rmL == 0 && rmR == 0 && bal == 0) res.insert(cur);
            return;
        }
        char c = str[i];
        if (c == '(') {
            if (rmL > 0) dfs(i + 1, rmL - 1, rmR, bal, cur);
            cur.push_back(c);
            dfs(i + 1, rmL, rmR, bal + 1, cur);
            cur.pop_back();
        } else if (c == ')') {
            if (rmR > 0) dfs(i + 1, rmL, rmR - 1, bal, cur);
            if (bal > 0) {
                cur.push_back(c);
                dfs(i + 1, rmL, rmR, bal - 1, cur);
                cur.pop_back();
            }
        } else {
            cur.push_back(c);
            dfs(i + 1, rmL, rmR, bal, cur);
            cur.pop_back();
        }
    }
    vector<string> removeInvalidParentheses(string s) {
        str = s;
        res.clear();
        int open = 0, rmR = 0;
        for (char c : s) {
            if (c == '(') open++;
            else if (c == ')') {
                if (open > 0) open--;
                else rmR++;
            }
        }
        string cur;
        dfs(0, open, rmR, 0, cur);
        return vector<string>(res.begin(), res.end());
    }
};
```

