Build an adjacency map from the pairs. In the original array, the two endpoints are the only values with exactly one neighbour. Start from one endpoint and walk the chain, each time moving to the neighbour that is not the previous element.

Details:
- Use an `unordered_map<int, vector<int>>` for adjacency.
- Pick any key whose neighbour list has size 1 as the start.
- The array has n = pairs.size() + 1 elements. Set `res[0] = start` and `res[1] = adj[start][0]`.
- For each later position i, the current element has at most two neighbours. Choose the one that differs from `res[i-2]`. Since all values are unique, this comparison is safe.

```cpp
class Solution {
public:
    vector<int> restoreArray(vector<vector<int>>& adjacentPairs) {
        unordered_map<int, vector<int>> adj;
        for (auto &p : adjacentPairs) {
            adj[p[0]].push_back(p[1]);
            adj[p[1]].push_back(p[0]);
        }
        int n = adjacentPairs.size() + 1;
        int start = 0;
        for (auto &kv : adj) {
            if (kv.second.size() == 1) {
                start = kv.first;
                break;
            }
        }
        vector<int> res(n);
        res[0] = start;
        res[1] = adj[start][0];
        for (int i = 2; i < n; i++) {
            auto &v = adj[res[i - 1]];
            res[i] = (v[0] == res[i - 2]) ? v[1] : v[0];
        }
        return res;
    }
};
```

