class Solution {
public:
    vector<int> getCoprimes(vector<int>& nums, vector<vector<int>>& edges) {
        int n = nums.size();
        vector<vector<int>> adj(n);
        for (auto &e : edges) {
            adj[e[0]].push_back(e[1]);
            adj[e[1]].push_back(e[0]);
        }
        bool cop[51][51];
        for (int i = 1; i <= 50; i++)
            for (int j = 1; j <= 50; j++)
                cop[i][j] = (__gcd(i, j) == 1);
        vector<int> ans(n, -1), parent(n, -1), depth(n, 0), idx(n, 0);
        vector<char> entered(n, 0);
        vector<vector<int>> stk(51);
        vector<int> st;
        st.push_back(0);
        while (!st.empty()) {
            int u = st.back();
            if (!entered[u]) {
                entered[u] = 1;
                int best = -1;
                for (int v = 1; v <= 50; v++) {
                    if (cop[nums[u]][v] && !stk[v].empty()) {
                        int c = stk[v].back();
                        if (best == -1 || depth[c] > depth[best]) best = c;
                    }
                }
                ans[u] = best;
                stk[nums[u]].push_back(u);
            }
            bool pushed = false;
            while (idx[u] < (int)adj[u].size()) {
                int v = adj[u][idx[u]++];
                if (v != parent[u]) {
                    parent[v] = u;
                    depth[v] = depth[u] + 1;
                    st.push_back(v);
                    pushed = true;
                    break;
