Count the soldiers in each row, pair each count with its row index, sort the pairs, and return the first k indices. Comparing `(count, index)` pairs handles ties by index automatically. With m ≤ 100 and n ≤ 100, this is easily fast enough.

```cpp
class Solution {
public:
    vector<int> kWeakestRows(vector<vector<int>>& mat, int k) {
        vector<pair<int,int>> v;
        for (int i = 0; i < (int)mat.size(); i++) {
            int c = 0;
            for (int x : mat[i]) c += x;
            v.push_back({c, i});
        }
        sort(v.begin(), v.end());
        vector<int> r;
        for (int i = 0; i < k; i++) r.push_back(v[i].second);
        return r;
    }
};
```

