A word is uncommon exactly when it appears once in the combined text of both sentences. So I count every word across both sentences in one map and return the words whose count is 1.

```cpp
class Solution {
public:
    vector<string> uncommonFromSentences(string s1, string s2) {
        unordered_map<string,int> cnt;
        string t = s1 + " " + s2;
        stringstream ss(t);
        string w;
        while (ss >> w) cnt[w]++;
        vector<string> res;
        for (auto &p : cnt) if (p.second == 1) res.push_back(p.first);
        return res;
    }
};
```

