traces.inference_trace:
Approach: breadth-first search from `beginWord`. Put all words from `wordList` into an unordered_set. For each word popped from the queue, try changing each position to each letter 'a'–'z'. If the new word is in the set, erase it (this marks it visited) and push it with distance + 1. When the new word equals `endWord`, return the distance.

If `endWord` is not in the set, return 0 straight away. The cost is about 5000 words × 10 positions × 26 letters, which is fine.

```cpp
class Solution {
public:
    int ladderLength(string beginWord, string endWord, vector<string>& wordList) {
        unordered_set<string> dict(wordList.begin(), wordList.end());
        if (!dict.count(endWord)) return 0;
        queue<pair<string,int>> q;
        q.push({beginWord, 1});
        dict.erase(beginWord);
        while (!q.empty()) {
            auto [w, d] = q.front();
            q.pop();
            for (size_t i = 0; i < w.size(); i++) {
                char orig = w[i];
                for (char c = 'a'; c <= 'z'; c++) {
                    if (c == orig) continue;
                    w[i] = c;
                    if (dict.count(w)) {
                        if (w == endWord) return d + 1;
                        dict.erase(w);
                        q.push({w, d + 1});
                    }
                }
                w[i] = orig;
            }
        }
        return 0;
    }
};
```

